  merge_configs: &[&serde_json::Value],
  reload: bool,
  target: Target,
  tauri_dir: &Path,
) -> crate::Result<ConfigMetadata> {

let cli_options = {
  let cli_options = { read_options(&tauri_config) };
  if !cli_options.config.is_empty() {
    // reload config with merges from the ios dev|build script
    reload_tauri_config(
      &mut tauri_config,
      &cli_options
        .config
        .iter()
        .map(|conf| &conf.0)
        .collect::<Vec<_>>(),
      dirs.tauri,
    )?
  };

  cli_options
};
